const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
const state={households:[],currentId:null,asOf:null,dashboard:null,incomes:[],expenses:[],transfers:[],credits:[],expenseFilter:'active',transferFilter:'active',creditFilter:'all',diagnostics:null,preview:null,previewMonth:null,previewAccountIds:[],previewCreditIds:[],previewSelectedDay:null,editingFlowId:null,editingFlowKind:null,editingAccountId:null,editingAccountHistory:[],editingTransferId:null,editingCreditId:null,currentCreditId:null};
const recurrenceLabels={weekly:'wöchentlich',monthly:'monatlich',quarterly:'vierteljährlich',semiannual:'halbjährlich',yearly:'jährlich',once:'einmalig'};
const categoryLabels={salary:'Gehalt',pension:'Rente',benefit:'Leistung',family:'Familie',other_income:'Sonstige Einnahme',housing:'Wohnen',energy:'Energie',insurance:'Versicherung',food:'Lebensmittel',mobility:'Mobilität',consumer_credit:'Konsumkredit',credit:'Kredit',borrowed:'Geliehen',leisure:'Freizeit',other_expense:'Sonstige Ausgabe',other:'Sonstiges'};
const creditTypeLabels={consumer_credit:'Konsumkredit',credit:'Kredit',borrowed:'Geliehen'};
const movementLabels={income:'Einnahme',expense:'Ausgabe',transfer_in:'Umbuchung +',transfer_out:'Umbuchung −'};
const incomeCategories=[['salary','Gehalt'],['pension','Rente'],['benefit','Leistung'],['family','Familie'],['other_income','Sonstige Einnahme']];
const expenseCategories=[['housing','Wohnen'],['energy','Energie'],['insurance','Versicherung'],['food','Lebensmittel'],['mobility','Mobilität'],['consumer_credit','Konsumkredit'],['credit','Kredit'],['borrowed','Geliehen'],['leisure','Freizeit'],['other_expense','Sonstige Ausgabe']];
const creditCategories=new Set(['consumer_credit','credit','borrowed']);

const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const eur=cents=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format((Number(cents)||0)/100);
const moneyOrMissing=cents=>cents==null?'Nicht hinterlegt':eur(cents);
const euroCents=value=>Math.round((Number.parseFloat(String(value).replace(',','.'))||0)*100);
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function monthNow(){return today().slice(0,7)}
function dateLabel(value){if(!value)return 'nicht hinterlegt';const [y,m,d]=String(value).split('-');return d?`${d}.${m}.${y}`:String(value)}
function monthLabel(value){if(!value)return '';const [y,m]=value.split('-').map(Number);return new Intl.DateTimeFormat('de-DE',{month:'long',year:'numeric'}).format(new Date(y,m-1,1))}
function weekdayLabel(value){const [y,m,d]=value.split('-').map(Number);return new Intl.DateTimeFormat('de-DE',{weekday:'long'}).format(new Date(y,m-1,d))}
function shiftDay(value,count){const [y,m,d]=value.split('-').map(Number),next=new Date(y,m-1,d+count);return `${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`}
function shiftMonth(value,count){const [y,m]=value.split('-').map(Number),next=new Date(y,m-1+count,1);return `${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}`}
function addMonthsToDate(value,count){if(!value||!count)return '';const [y,m,d]=value.split('-').map(Number),monthIndex=m-1+Number(count),year=y+Math.floor(monthIndex/12),month=((monthIndex%12)+12)%12;const lastDay=new Date(year,month+1,0).getDate();return `${year}-${String(month+1).padStart(2,'0')}-${String(Math.min(d,lastDay)).padStart(2,'0')}`}
function durationBetweenDates(start,end){if(!start||!end)return '';const [sy,sm]=start.split('-').map(Number),[ey,em]=end.split('-').map(Number),months=(ey-sy)*12+em-sm;return months>0&&addMonthsToDate(start,months)===end?String(months):''}
function expectedTransferEnd(start,recurrence,count){const total=Number(count);if(!start||!Number.isInteger(total)||total<1)return '';if(recurrence==='once')return total===1?start:'';const interval={monthly:1,quarterly:3,semiannual:6,yearly:12}[recurrence];return interval?addMonthsToDate(start,(total-1)*interval):''}
function transferLimitError(form){const end=form.end_date.value,count=form.occurrence_count.value;if(!count)return '';if(form.recurrence.value==='once'&&Number(count)!==1)return 'Eine einmalige Umbuchung kann nur eine Ausführung haben.';if(!end)return '';const expected=expectedTransferEnd(form.due_date.value,form.recurrence.value,count);return expected&&end!==expected?`Enddatum und Anzahl passen nicht zusammen. Bei ${count} Ausführungen ist das Enddatum ${dateLabel(expected)}.`:''}
function ownerName(item){if(item.owner_scope==='joint')return 'Gemeinsam';return state.dashboard?.household.persons.find(person=>person.id===item.owner_person_id)?.display_name||'Haushalt'}
function accountById(id){return state.dashboard?.household.accounts.find(account=>account.id===id)}
function accountName(id){return accountById(id)?.name||'Kein Konto'}
function creditById(id){return state.credits.find(credit=>credit.id===id)}
function creditName(id){return creditById(id)?.name||'Kein Kredit'}
function slotForOwner(item){if(item?.owner_scope==='joint')return 'joint';return state.dashboard.household.persons.find(person=>person.id===item?.owner_person_id)?.slot||'A'}
function isArchived(item){const archiveDate=item?.end_date||(item?.recurrence==='once'?item?.due_date:null);return item?.lifecycle_status==='ended'||Boolean(archiveDate&&archiveDate<today())}
async function api(url,options={}){const response=await fetch(url,options),data=await response.json().catch(()=>({error:'Ungültige Serverantwort.'}));if(!response.ok)throw new Error(data.error||'Anfrage fehlgeschlagen.');return data}
function toast(message){const element=$('#toast');element.textContent=message;element.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>element.hidden=true,3800)}

async function boot(){state.asOf=today();state.previewMonth=monthNow();state.households=(await api('/api/households')).items;state.currentId=state.households[0]?.id||null;if(!state.currentId){$('#app').hidden=false;renderHouseholdSelect();openSetup(true);return}await loadAll();$('#app').hidden=false}
async function loadAll(){const query=`household_id=${encodeURIComponent(state.currentId)}&as_of=${encodeURIComponent(state.asOf)}`,managementQuery=`household_id=${encodeURIComponent(state.currentId)}&as_of=${encodeURIComponent(today())}`;const [dashboard,incomes,expenses,transfers,credits,diagnostics]=await Promise.all([api(`/api/dashboard?${query}`),api(`/api/cash-flows?${managementQuery}&kind=income`),api(`/api/cash-flows?${managementQuery}&kind=expense`),api(`/api/transfers?household_id=${encodeURIComponent(state.currentId)}`),api(`/api/credits?household_id=${encodeURIComponent(state.currentId)}&as_of=${encodeURIComponent(today())}`),api(`/api/diagnostics?${query}`)]);state.dashboard=dashboard;state.incomes=incomes.items;state.expenses=expenses.items;state.transfers=transfers.items;state.credits=credits.items;state.diagnostics=diagnostics;ensureSelections();renderAll();await loadPreview()}
function ensureSelections(){const ids=state.dashboard.household.accounts.map(account=>account.id),valid=new Set(ids);state.previewAccountIds=state.previewAccountIds.filter(id=>valid.has(id));if(!state.previewAccountIds.length)state.previewAccountIds=[...ids];const creditIds=state.credits.map(credit=>credit.id),validCredits=new Set(creditIds);state.previewCreditIds=state.previewCreditIds.filter(id=>validCredits.has(id))}
function renderAll(){renderHouseholdSelect();renderDashboard();renderManage();renderExpenses();renderCredits();renderTransfers();renderSettings();$('#dashboard-date').value=state.asOf;$('#preview-month-label').textContent=monthLabel(state.previewMonth);$('#current-household-name').textContent=state.dashboard.household.name}

function renderHouseholdSelect(){const select=$('#household-select');select.innerHTML=state.households.map(h=>`<option value="${escapeHtml(h.id)}" ${h.id===state.currentId?'selected':''}>${escapeHtml(h.name)}</option>`).join('');const current=state.households.find(h=>h.id===state.currentId);$('#current-household-name').textContent=current?.name||'Noch keiner';$('#delete-household').disabled=!current}
function warningHtml(warnings){return (warnings||[]).map(item=>`<div class="overdraft-warning">Disporahmen bei <b>${escapeHtml(item.name)}</b> um ${eur(item.overage_cents)} überschritten.</div>`).join('')}
function accountRow(account,editable=false){const projected=account.projected_balance_cents??account.balance_cents,changed=projected!=null&&account.balance_cents!=null&&projected!==account.balance_cents;return `<article class="account-row ${account.overdraft_exceeded?'overdraft-card':''}"><div><div class="account-meta"><h3>${escapeHtml(account.name)}</h3>${account.is_default?'<span class="default-badge">Standardkonto</span>':''}${account.overdraft_exceeded?'<span class="warning-badge">Dispo überschritten</span>':''}</div><small>Stand ${dateLabel(account.anchor_date)} · ${account.bookings_applied?'Tagesbuchungen enthalten':'Tagesbuchungen werden berechnet'}</small></div><strong class="${projected<0?'amount-negative':''}">${moneyOrMissing(projected)}</strong><small>${changed?`Gespeichert ${eur(account.balance_cents)} · `:''}${Number(account.overdraft_limit_cents)>0?`Dispo ${eur(account.overdraft_limit_cents)}`:'Kein Dispo'}</small>${editable?`<div class="row-actions"><button class="link-button" type="button" data-edit-account="${escapeHtml(account.id)}">Bearbeiten &amp; Stand erfassen</button></div>`:''}</article>`}
function renderDashboard(){const m=state.dashboard.metrics,accounts=state.dashboard.household.accounts,creditSummary=state.dashboard.credit_summary||{groups:[]};$('#dashboard-balance').textContent=eur(m.balance_cents);$('#dashboard-balance').classList.toggle('amount-negative',m.balance_cents<0);$('#dashboard-balance-note').textContent=accounts.length?`Berechnet bis ${dateLabel(state.dashboard.as_of)}`:'Noch kein Konto angelegt';$('#dashboard-income').textContent=eur(m.income_cents);$('#dashboard-expenses').textContent=eur(m.expenses_cents);$('#dashboard-surplus').textContent=eur(m.surplus_cents);$('#dashboard-account-count').textContent=accounts.length;$('#dashboard-as-of').textContent=dateLabel(state.dashboard.as_of);$('#dashboard-credit-as-of').textContent=`Stand ${dateLabel(creditSummary.as_of)}`;$('#dashboard-credit-summary').innerHTML=(creditSummary.groups||[]).map(group=>creditSummaryCard(group)).join('');$('#dashboard-warnings').innerHTML=warningHtml(state.dashboard.overdraft_warnings);$('#dashboard-account-list').innerHTML=accounts.length?accounts.map(account=>accountRow(account)).join(''):'<p class="empty">Noch kein Konto angelegt.</p>';const breakdowns=state.dashboard.breakdowns||{};$('#dashboard-breakdowns').innerHTML=breakdownCard('Einnahmen',breakdowns.income,'income')+breakdownCard('Ausgaben',breakdowns.expenses,'expense')}
function creditSummaryCard(group){return `<article class="summary-card"><span>${escapeHtml(creditTypeLabels[group.credit_type]||group.credit_type)} · ${group.count}</span><b>${eur(group.balance_cents)}</b><small>offener Gesamtsaldo</small></article>`}
function breakdownCard(title,items,kind){const values=(items||[]).sort((a,b)=>b.amount_cents-a.amount_cents),max=Math.max(...values.map(item=>item.amount_cents),1);return `<article class="breakdown-card"><h3>${title}</h3><div class="bar-list">${values.length?values.map(item=>`<div class="bar-row"><span>${escapeHtml(item.label)}</span><b>${eur(item.amount_cents)}</b><div class="bar ${kind}"><i style="width:${Math.max(4,item.amount_cents/max*100)}%"></i></div></div>`).join(''):'<p class="empty">Keine Werte</p>'}</div></article>`}

function flowRow(item){const account=accountName(item.account_id),kind=item.kind==='income'?'income':'expense',end=item.end_date?` · endet ${dateLabel(item.end_date)}`:'',credit=item.credit_id?` · ${escapeHtml(creditName(item.credit_id))} · Tilgung ${eur(item.credit_reduction_cents)}`:'';return `<article class="flow-row ${item.configured_active?'':'inactive'}"><span><b>${escapeHtml(item.name)}</b><small>${escapeHtml(categoryLabels[item.category]||'Sonstiges')} · ${dateLabel(item.due_date)} · ${recurrenceLabels[item.recurrence]||item.recurrence}${end} · ${escapeHtml(account)}${credit}${state.dashboard.household.mode==='couple'?` · ${escapeHtml(ownerName(item))}`:''}</small></span><strong class="${kind==='expense'?'amount-negative':''}">${kind==='expense'?'− ':'+ '}${eur(item.amount_cents)}</strong><button class="link-button" type="button" data-edit-flow-kind="${kind}" data-edit-flow="${escapeHtml(item.id)}">Bearbeiten</button></article>`}
function lifecycleFilter(filter,activeCount,archiveCount,attribute){return `<button class="credit-filter-button ${filter==='active'?'active':''}" type="button" data-${attribute}="active" aria-pressed="${filter==='active'}">Aktiv <span>${activeCount}</span></button><button class="credit-filter-button ${filter==='archive'?'active':''}" type="button" data-${attribute}="archive" aria-pressed="${filter==='archive'}">Archiv <span>${archiveCount}</span></button>`}
function renderManage(){const accounts=state.dashboard.household.accounts;$('#manage-account-list').innerHTML=accounts.length?accounts.map(account=>accountRow(account,true)).join(''):'<p class="empty">Lege dein erstes Konto an.</p>';$('#income-list').innerHTML=state.incomes.length?state.incomes.map(flowRow).join(''):'<p class="empty">Noch keine Einnahme angelegt.</p>';$('#income-position-total').textContent=`+ ${eur(state.incomes.reduce((sum,item)=>sum+Number(item.amount_cents||0),0))}`}
function renderExpenses(){const active=state.expenses.filter(item=>!isArchived(item)),archive=state.expenses.filter(isArchived),visible=state.expenseFilter==='archive'?archive:active;$('#expense-list-title').textContent=state.expenseFilter==='archive'?'Archivierte Ausgaben':'Aktive Ausgaben';$('#expense-filter').innerHTML=lifecycleFilter(state.expenseFilter,active.length,archive.length,'expense-filter');$('#expense-list').innerHTML=visible.length?visible.map(flowRow).join(''):`<p class="empty">${state.expenseFilter==='archive'?'Noch keine archivierte Ausgabe vorhanden.':'Noch keine aktive Ausgabe angelegt.'}</p>`;$('#expense-position-total').textContent=`− ${eur(state.expenses.reduce((sum,item)=>sum+Number(item.amount_cents||0),0))}`}
function renderCredits(){const types=['consumer_credit','credit','borrowed'],groups=types.map(type=>{const credits=state.credits.filter(item=>item.credit_type===type);return {credit_type:type,count:credits.length,balance_cents:credits.reduce((sum,item)=>sum+Number(item.remaining_balance_cents||0),0)}}),filters=[['all','Alle'],...types.map(type=>[type,creditTypeLabels[type]])],filtered=state.creditFilter==='all'?state.credits:state.credits.filter(item=>item.credit_type===state.creditFilter),activeLabel=state.creditFilter==='all'?'Alle Kredite':creditTypeLabels[state.creditFilter];$('#credit-page-summary').innerHTML=groups.map(creditSummaryCard).join('');$('#credit-list-title').textContent=activeLabel;$('#credit-filter').innerHTML=filters.map(([value,label])=>{const count=value==='all'?state.credits.length:groups.find(group=>group.credit_type===value).count,active=state.creditFilter===value;return `<button class="credit-filter-button ${active?'active':''}" type="button" data-credit-filter="${value}" aria-pressed="${active}">${escapeHtml(label)} <span>${count}</span></button>`}).join('');$('#credit-list').innerHTML=filtered.length?filtered.map(item=>`<article class="credit-row" data-open-credit="${escapeHtml(item.id)}"><div><span class="credit-type-badge">${escapeHtml(creditTypeLabels[item.credit_type])}</span><h3>${escapeHtml(item.name)}</h3><small>Ausgang ${eur(item.opening_balance_cents)} · getilgt ${eur(item.paid_cents)}</small></div><strong>${eur(item.remaining_balance_cents)}</strong><small>offener Saldo</small><button class="link-button" type="button" data-edit-credit="${escapeHtml(item.id)}">Bearbeiten</button></article>`).join(''):state.credits.length?`<p class="empty">Keine Kredite der Art „${escapeHtml(activeLabel)}“ vorhanden.</p>`:'<p class="empty">Noch kein Kredit angelegt.</p>'}
function renderTransfers(){const active=state.transfers.filter(item=>!isArchived(item)),archive=state.transfers.filter(isArchived),visible=state.transferFilter==='archive'?archive:active;$('#transfer-list-title').textContent=state.transferFilter==='archive'?'Archivierte Umbuchungen':'Aktive Umbuchungen';$('#transfer-filter').innerHTML=lifecycleFilter(state.transferFilter,active.length,archive.length,'transfer-filter');$('#transfer-list').innerHTML=visible.length?visible.map(item=>{const end=item.end_date?` · Ende ${dateLabel(item.end_date)}`:'',count=item.occurrence_count?` · ${item.occurrence_count} Ausführung${Number(item.occurrence_count)===1?'':'en'}`:'';return `<article class="flow-row ${item.active?'':'inactive'}"><span><b>${escapeHtml(item.name)}</b><small>${dateLabel(item.due_date)} · ${recurrenceLabels[item.recurrence]}${end}${count} · ${escapeHtml(item.source_account_name)} → ${escapeHtml(item.target_account_name)}</small></span><strong>${eur(item.amount_cents)}</strong><button class="link-button" type="button" data-edit-transfer="${escapeHtml(item.id)}">Bearbeiten</button></article>`}).join(''):`<p class="empty">${state.transferFilter==='archive'?'Noch keine archivierte Umbuchung vorhanden.':'Noch keine aktive Umbuchung angelegt.'}</p>`}
function renderSettings(){const persons=state.dashboard.household.persons;$('#person-list').innerHTML=persons.map(person=>`<article class="person-row"><span class="avatar">${escapeHtml(person.display_name.slice(0,1).toUpperCase())}</span><span><b>${escapeHtml(person.display_name)}</b><small>Person ${escapeHtml(person.slot)}</small></span></article>`).join('');$('#diagnostics-as-of').textContent=dateLabel(state.diagnostics.as_of);const s=state.diagnostics.summary;$('#diagnostics-summary').innerHTML=summaryCard('Betroffene Positionen',s.item_count)+summaryCard('Nicht berücksichtigt',s.not_considered_count)+summaryCard('Fehler',s.error,'negative')+summaryCard('Warnungen',s.warning);$('#diagnostics-list').innerHTML=state.diagnostics.items.length?state.diagnostics.items.map(item=>`<article class="diagnostic-row"><i class="severity ${item.issues.some(issue=>issue.severity==='error')?'error':'warning'}"></i><div><b>${escapeHtml(item.name)}</b><small>${item.kind==='income'?'Einnahme':'Ausgabe'} · ${eur(item.amount_cents)}</small><ul>${item.issues.map(issue=>`<li>${escapeHtml(issue.message)}</li>`).join('')}</ul></div><button class="link-button" type="button" data-edit-flow-kind="${item.kind}" data-edit-flow="${escapeHtml(item.id)}">Bearbeiten</button></article>`).join(''):'<div class="notice">Alle Einnahmen und Ausgaben können berücksichtigt werden.</div>'}
function summaryCard(label,value,style=''){const countLabels=new Set(['Betroffene Positionen','Nicht berücksichtigt','Fehler','Warnungen','Ausgewählte Konten','Bewegungen','Buchungen']);const display=typeof value==='number'&&!countLabels.has(label)?eur(value):value;return `<article class="summary-card ${style}"><span>${escapeHtml(label)}</span><b class="${style==='negative'?'amount-negative':''}">${escapeHtml(display)}</b></article>`}

function renderAccountSelectors(target,selectedIds,mode){const accounts=state.dashboard.household.accounts;target.innerHTML=accounts.length?accounts.map(account=>`<label class="account-choice"><input type="checkbox" data-${mode}-account="${escapeHtml(account.id)}" ${selectedIds.includes(account.id)?'checked':''}> ${escapeHtml(account.name)}</label>`).join(''):'<p class="empty">Noch keine Konten vorhanden.</p>'}
function renderCreditSelectors(){const target=$('#preview-credit-selectors');target.innerHTML=state.credits.length?state.credits.map(credit=>`<label class="account-choice credit-choice"><input type="checkbox" data-preview-credit="${escapeHtml(credit.id)}" ${state.previewCreditIds.includes(credit.id)?'checked':''}> ${escapeHtml(credit.name)}</label>`).join(''):'<p class="empty">Noch keine Kredite vorhanden.</p>'}
function movementRow(item){const negative=Number(item.amount_cents)<0,skipped=item.skip_reason==='credit_repaid',residual=Number(item.final_residual_added_cents||0),adjusted=Boolean(item.credit_adjusted)&&!skipped,status=skipped?' · entfällt – Kredit bereits getilgt':residual>0?` · Restbetrag ${eur(residual)} in Schlussrate enthalten`:adjusted?` · Schlussrate von ${eur(item.planned_amount_cents)} auf ${eur(Math.abs(item.amount_cents))} begrenzt`:item.completed?' · erledigt – nicht eingerechnet':(item.applied_to_projection===false?' · bereits im Kontostand enthalten':''),completion=item.completion_allowed?`<label class="movement-completion"><input type="checkbox" data-movement-completion="${escapeHtml(item.completion_key)}" ${item.completed?'checked':''}> Vorgang erledigt</label>`:'';return `<article class="movement-row ${item.completed?'completed':''} ${skipped?'skipped':''}"><span class="movement-kind ${escapeHtml(item.kind)}">${escapeHtml(movementLabels[item.kind]||'Buchung')}</span><span><b>${escapeHtml(item.label)}</b><small>${dateLabel(item.date)} · ${escapeHtml(accountName(item.account_id))}${status}</small></span><strong class="${negative?'amount-negative':''}">${skipped?'0,00 €':`${negative?'− ':'+ '}${eur(Math.abs(item.amount_cents))}`}</strong>${completion}</article>`}
async function loadPreview(){if(!state.currentId)return;state.preview=await api('/api/preview/monthly',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({household_id:state.currentId,month:state.previewMonth,account_ids:state.previewAccountIds,credit_ids:state.previewCreditIds})});renderPreview()}
function creditPaymentRow(item){const skipped=item.skip_reason==='credit_repaid',residual=Number(item.final_residual_added_cents||0),adjusted=Boolean(item.adjusted)&&!skipped,status=skipped?' · entfällt – Kredit bereits getilgt':residual>0?` · Restbetrag ${eur(residual)} zugeschlagen`:adjusted?` · auf Restschuld begrenzt (geplant ${eur(item.planned_amount_cents)})`:item.future?' · geplant':'';return `<article class="credit-payment-row ${item.future?'future':''} ${skipped?'skipped':''}"><span><b>${escapeHtml(item.label)}</b><small>${dateLabel(item.date)} · ${item.source==='expense'?'aus Ausgabe':'manuell'}${status}</small></span><strong>${skipped?'0,00 €':`− ${eur(item.amount_cents)}`}</strong>${item.source==='manual'?`<button class="link-button" type="button" data-delete-credit-payment="${escapeHtml(item.id)}">Löschen</button>`:'<span></span>'}</article>`}
function renderPreview(){renderAccountSelectors($('#preview-account-selectors'),state.previewAccountIds,'preview');renderCreditSelectors();const result=state.preview,t=result.totals,ct=result.credit_totals||{opening_balance_cents:0,closing_balance_cents:0,reduction_cents:0};$('#preview-month-label').textContent=monthLabel(result.month);$('#preview-summary').innerHTML=summaryCard('Konten am Monatsanfang',t.opening_balance_cents)+summaryCard('Einnahmen',t.income_cents)+summaryCard('Ausgaben',t.expense_cents)+summaryCard('Konten am Monatsende',t.closing_balance_cents,t.closing_balance_cents<0?'negative':'');$('#preview-credit-summary').innerHTML=state.previewCreditIds.length?summaryCard('Kredite am Monatsanfang',ct.opening_balance_cents)+summaryCard('Simulierte Tilgung',ct.reduction_cents)+summaryCard('Kredite am Monatsende',ct.closing_balance_cents):'';$('#preview-warnings').innerHTML=warningHtml(result.overdraft_warnings);$('#preview-range').textContent=`${dateLabel(result.from)} – ${dateLabel(result.through)}`;const days=result.days||[];if(!result.accounts.length&&!result.credits.length){$('#preview-day-list').innerHTML='<p class="empty">Wähle mindestens ein Konto oder einen Kredit.</p>';updatePreviewDayNavigation();return}$('#preview-day-list').innerHTML=days.map(day=>{const open=state.previewSelectedDay===day.date,balances=(day.balances||[]).map(account=>`<span class="day-balance ${account.overdraft_exceeded?'warning':''}"><small>${escapeHtml(account.name)}</small><b class="${Number(account.projected_balance_cents)<0?'amount-negative':''}">${moneyOrMissing(account.projected_balance_cents)}</b></span>`).join(''),credits=(day.credits||[]).map(credit=>`<span class="day-balance credit-balance"><small>${escapeHtml(credit.name)} · Kredit</small><b>${eur(credit.remaining_balance_cents)}</b>${credit.reduction_cents?`<em>− ${eur(credit.reduction_cents)} Tilgung</em>`:''}</span>`).join('');const warning=day.overdraft_warning_count?'<div class="day-warning">Disporahmen an diesem Tag überschritten.</div>':'',creditMovements=(day.credits||[]).flatMap(credit=>credit.payments||[]);return `<details class="day-entry ${day.overdraft_warning_count?'has-warning':''}" data-preview-day-entry="${escapeHtml(day.date)}" ${open?'open':''}><summary data-preview-day="${escapeHtml(day.date)}"><span class="day-date"><b>${escapeHtml(weekdayLabel(day.date))}</b><small>${dateLabel(day.date)}</small></span><span class="day-balances">${balances}${credits}</span><span class="day-total"><small>Konten gesamt</small><b class="${day.total_balance_cents<0?'amount-negative':''}">${eur(day.total_balance_cents)}</b><em class="${day.delta_cents<0?'amount-negative':''}">${day.delta_cents===0?'keine Kontobewegung':`${day.delta_cents>0?'+ ':''}${eur(day.delta_cents)}`}</em></span></summary><div class="day-detail">${warning}<div class="movement-list">${day.movements.length?day.movements.map(movementRow).join(''):'<p class="empty">An diesem Tag sind keine Kontobewegungen fällig.</p>'}${creditMovements.length?`<div class="credit-movement-separator"><p class="eyebrow">KREDITVERÄNDERUNGEN · NICHT IN DER KONTENSUMME</p>${creditMovements.map(creditPaymentRow).join('')}</div>`:''}</div></div></details>`}).join('');updatePreviewDayNavigation()}
function updatePreviewDayNavigation(){const navigation=$('#preview-day-navigation');navigation.hidden=!state.previewSelectedDay;$('#preview-selected-day-label').textContent=state.previewSelectedDay?`${weekdayLabel(state.previewSelectedDay)}, ${dateLabel(state.previewSelectedDay)}`:''}
function selectPreviewDay(value,scroll=true){state.previewSelectedDay=value;$$('[data-preview-day-entry]').forEach(entry=>entry.open=entry.dataset.previewDayEntry===value);updatePreviewDayNavigation();if(scroll)$(`[data-preview-day-entry="${value}"]`)?.scrollIntoView({behavior:'smooth',block:'center'})}
function movePreviewDay(count){const start=state.previewSelectedDay||(state.previewMonth===monthNow()?today():`${state.previewMonth}-01`),next=shiftDay(start,count);if(next.slice(0,7)!==state.previewMonth){state.previewMonth=next.slice(0,7);state.previewSelectedDay=next;loadPreview()}else selectPreviewDay(next)}

function showView(name){$$('.view').forEach(view=>view.hidden=view.id!==`${name}-view`);$$('.nav-item').forEach(button=>button.classList.toggle('active',button.dataset.view===name));location.hash=name}
$$('[data-view]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.view)));
$$('[data-show-view]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();showView(link.dataset.showView)}));
function setDate(value){state.asOf=value;return loadAll()}
$('#dashboard-prev').addEventListener('click',()=>setDate(shiftDay(state.asOf,-1)));$('#dashboard-next').addEventListener('click',()=>setDate(shiftDay(state.asOf,1)));$('#dashboard-today').addEventListener('click',()=>setDate(today()));$('#dashboard-date').addEventListener('change',event=>setDate(event.target.value));
function changePreviewMonth(count){state.previewMonth=shiftMonth(state.previewMonth,count);state.previewSelectedDay=null;loadPreview()}
$('#preview-minus').addEventListener('click',()=>changePreviewMonth(-1));$('#preview-plus').addEventListener('click',()=>changePreviewMonth(1));$('#preview-plus-two').addEventListener('click',()=>changePreviewMonth(2));$('#preview-current').addEventListener('click',()=>{state.previewMonth=monthNow();state.previewSelectedDay=null;loadPreview()});$('#preview-day-prev').addEventListener('click',()=>movePreviewDay(-1));$('#preview-day-next').addEventListener('click',()=>movePreviewDay(1));
$('#preview-day-list').addEventListener('click',event=>{const summary=event.target.closest('[data-preview-day]');if(!summary)return;const details=summary.closest('details'),value=summary.dataset.previewDay;setTimeout(()=>{if(details.open)selectPreviewDay(value,false);else if(state.previewSelectedDay===value){state.previewSelectedDay=null;updatePreviewDayNavigation()}$$('[data-preview-day-entry]').forEach(entry=>{if(entry!==details)entry.open=false})},0)});
$('#preview-day-list').addEventListener('change',async event=>{const input=event.target.closest('[data-movement-completion]');if(!input)return;const completed=input.checked;input.disabled=true;try{await api('/api/movement-completion',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({household_id:state.currentId,occurrence_key:input.dataset.movementCompletion,completed})});await loadAll();toast(completed?'Vorgang wurde als erledigt gespeichert.':'Vorgang wird wieder in der Vorschau berücksichtigt.')}catch(err){input.checked=!completed;input.disabled=false;toast(err.message)}});
