$('#setup-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget.elements,error=$('#setup-error'),button=event.submitter;error.hidden=true;button.disabled=true;const payload={name:form.name.value,mode:form.mode.value,person_a:form.person_a.value,person_b:form.person_b.value,account:form.account_name.value?{name:form.account_name.value,owner:'A',balance_cents:euroCents(form.balance.value),anchor_date:form.anchor_date.value,overdraft_limit_cents:euroCents(form.overdraft_limit.value),bookings_applied:form.bookings_applied.checked}:null};try{const household=await api('/api/households',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});state.households=(await api('/api/households')).items;state.currentId=household.id;state.previewAccountIds=[];state.previewCreditIds=[];$('#setup-dialog').close();await loadAll();showView('dashboard');toast('Haushalt wurde angelegt.')}catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false}});

function updateAccountBookingsHint(){const form=$('#account-form').elements,date=dateLabel(form.anchor_date.value),checked=form.bookings_applied.checked,hint=$('#account-bookings-hint');hint.textContent=checked?`Aktiv: Fällige Zahlungen am ${date} werden nicht erneut berechnet.`:`Nicht aktiv: Fällige Zahlungen am ${date} werden zum eingegebenen Kontostand hinzugerechnet oder davon abgezogen.`;hint.classList.toggle('active',checked)}
function applyAccountEntryForDate(){if(!state.editingAccountId){updateAccountBookingsHint();return}const form=$('#account-form').elements,entry=state.editingAccountHistory.find(item=>item.anchor_date===form.anchor_date.value);if(entry){form.balance.value=(Number(entry.balance_cents)/100).toFixed(2);form.bookings_applied.checked=Boolean(entry.bookings_applied)}else if(form.anchor_date.value===state.asOf){const account=accountById(state.editingAccountId);form.balance.value=account?.projected_balance_cents==null?'0.00':(Number(account.projected_balance_cents)/100).toFixed(2);form.bookings_applied.checked=false}updateAccountBookingsHint()}
async function openAccount(account=null){const form=$('#account-form');form.reset();state.editingAccountId=account?.id||null;state.editingAccountHistory=[];const h=state.dashboard.household;$('#account-owner').innerHTML=h.persons.map(person=>`<option value="${escapeHtml(person.slot)}">${escapeHtml(person.display_name)}</option>`).join('')+(h.mode==='couple'?'<option value="joint">Gemeinsam</option>':'');form.elements.anchor_date.value=state.asOf||today();form.elements.balance.value='0.00';form.elements.overdraft_limit.value=(Number(account?.overdraft_limit_cents||0)/100).toFixed(2);form.elements.is_default.checked=Boolean(account?.is_default);form.elements.bookings_applied.checked=false;if(account){form.elements.name.value=account.name;form.elements.owner.value=slotForOwner(account)}else{form.elements.owner.value='A'}$('#account-dialog-eyebrow').textContent=account?'KONTO UND HISTORIE':'KONTO ANLEGEN';$('#account-dialog-title').textContent=account?'Konto bearbeiten':'Konto anlegen';$('#account-submit').textContent=account?'Änderungen und Kontostand speichern':'Konto anlegen';$('#delete-account').hidden=!account;$('#account-error').hidden=true;const history=$('#account-history');history.hidden=!account;if(account){state.editingAccountHistory=(await api(`/api/accounts/${encodeURIComponent(account.id)}/balances?household_id=${encodeURIComponent(state.currentId)}`)).items;history.innerHTML=`<h3>Kontostand-Historie</h3>${state.editingAccountHistory.map(item=>`<article class="history-row"><span><b>${dateLabel(item.anchor_date)}</b><small>${item.bookings_applied?'Tagesbuchungen bereits enthalten':'Tagesbuchungen werden ab diesem Stand berechnet'} · ${item.source==='statement'?'historischer Altbestand':'manuell'}</small></span><strong class="${item.balance_cents<0?'amount-negative':''}">${eur(item.balance_cents)}</strong>${item.source==='manual'?`<button class="link-button" type="button" data-delete-balance="${escapeHtml(item.id)}">Löschen</button>`:''}</article>`).join('')}`;}applyAccountEntryForDate();if(!$('#account-dialog').open)$('#account-dialog').showModal()}
$('#new-account').addEventListener('click',()=>openAccount());$('#manage-account-list').addEventListener('click',event=>{const button=event.target.closest('[data-edit-account]');if(button){const account=accountById(button.dataset.editAccount);if(account)openAccount(account)}});
$('#account-form [name="bookings_applied"]').addEventListener('change',updateAccountBookingsHint);$('#account-form [name="anchor_date"]').addEventListener('change',applyAccountEntryForDate);
$('#account-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget.elements,error=$('#account-error'),button=event.submitter;button.disabled=true;error.hidden=true;const payload={household_id:state.currentId,name:form.name.value,owner:form.owner.value,balance_cents:euroCents(form.balance.value),anchor_date:form.anchor_date.value,bookings_applied:form.bookings_applied.checked,overdraft_limit_cents:euroCents(form.overdraft_limit.value),is_default:form.is_default.checked};try{const editedAccountId=state.editingAccountId,saved=await api(editedAccountId?`/api/accounts/${encodeURIComponent(editedAccountId)}`:'/api/accounts',{method:editedAccountId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),savedAccount=saved.accounts?.find(account=>editedAccountId?account.id===editedAccountId:account.name===payload.name);if(!savedAccount||savedAccount.anchor_date!==payload.anchor_date||Number(savedAccount.balance_cents)!==payload.balance_cents||Boolean(savedAccount.bookings_applied)!==payload.bookings_applied)throw new Error('Der gespeicherte Kontostand konnte nicht bestätigt werden. Bitte erneut versuchen.');state.asOf=payload.anchor_date;$('#account-dialog').close();state.editingAccountId=null;state.editingAccountHistory=[];await loadAll();toast(`Kontostand am ${dateLabel(payload.anchor_date)} wurde gespeichert.`)}catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false}});
$('#delete-account').addEventListener('click',async()=>{const account=accountById(state.editingAccountId);if(!account)return;const message=`Konto „${account.name}“ wirklich löschen?\n\nDie Kontostand-Historie und alle Umbuchungen dieses Kontos werden gelöscht. Einnahmen und Ausgaben bleiben erhalten, verlieren aber ihre Kontozuordnung.`;if(!confirm(message))return;const button=$('#delete-account'),error=$('#account-error');button.disabled=true;error.hidden=true;try{const result=await api(`/api/accounts/${encodeURIComponent(account.id)}?household_id=${encodeURIComponent(state.currentId)}`,{method:'DELETE'});state.previewAccountIds=state.previewAccountIds.filter(id=>id!==account.id);$('#account-dialog').close();state.editingAccountId=null;state.editingAccountHistory=[];await loadAll();toast(`Konto wurde gelöscht. ${result.unassigned_cash_flow_count} Position(en) sind jetzt ohne Konto.`)}catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false}});
$('#account-history').addEventListener('click',async event=>{const button=event.target.closest('[data-delete-balance]');if(!button||!state.editingAccountId)return;if(!confirm('Diesen historischen Kontostand wirklich löschen?'))return;try{await api(`/api/accounts/${encodeURIComponent(state.editingAccountId)}/balances/${encodeURIComponent(button.dataset.deleteBalance)}?household_id=${encodeURIComponent(state.currentId)}`,{method:'DELETE'});const account=accountById(state.editingAccountId);await loadAll();await openAccount(accountById(account.id));toast('Kontostand wurde aus der Historie entfernt.')}catch(err){toast(err.message)}});

function flowById(kind,id){return (kind==='income'?state.incomes:state.expenses).find(item=>item.id===id)}
function configureFlowRecurrences(kind){const select=$('#cash-flow-form').elements.recurrence,weekly=select.querySelector('option[value="weekly"]'),expense=kind==='expense';weekly.hidden=!expense;weekly.disabled=!expense;if(!expense&&select.value==='weekly')select.value='monthly'}
function configureFlowEndFields(kind){const expense=kind==='expense';$('#cash-flow-end-date-field').hidden=!expense;$('#cash-flow-duration-field').hidden=!expense;const form=$('#cash-flow-form').elements;form.end_date.disabled=!expense;form.duration_months.disabled=!expense}
function configureFlowCreditFields(){const form=$('#cash-flow-form').elements,isCredit=state.editingFlowKind==='expense'&&creditCategories.has(form.category.value),field=$('#cash-flow-credit-fields'),current=form.credit_id.value;field.hidden=!isCredit;form.credit_id.disabled=!isCredit;form.credit_reduction.disabled=!isCredit;if(!isCredit){form.credit_id.value='';form.credit_reduction.value='';return}const matches=state.credits.filter(credit=>credit.credit_type===form.category.value);$('#cash-flow-credit').innerHTML=matches.length?matches.map(credit=>`<option value="${escapeHtml(credit.id)}">${escapeHtml(credit.name)} · offen ${eur(credit.remaining_balance_cents)}</option>`).join(''):'<option value="">Zuerst passenden Kredit anlegen</option>';form.credit_id.value=matches.some(credit=>credit.id===current)?current:(matches[0]?.id||'')}
function syncFlowEndFromDuration(){const form=$('#cash-flow-form').elements,duration=Number(form.duration_months.value);if(state.editingFlowKind==='expense'&&form.due_date.value&&Number.isInteger(duration)&&duration>0)form.end_date.value=addMonthsToDate(form.due_date.value,duration)}
function syncFlowDurationFromEnd(){const form=$('#cash-flow-form').elements;if(state.editingFlowKind!=='expense')return;form.duration_months.value=durationBetweenDates(form.due_date.value,form.end_date.value)}
function openFlow(kind,item=null){
  state.editingFlowKind=kind;state.editingFlowId=item?.id||null;
  const form=$('#cash-flow-form');form.reset();configureFlowRecurrences(kind);configureFlowEndFields(kind);
  const h=state.dashboard.household,categories=kind==='income'?incomeCategories:expenseCategories;
  $('#cash-flow-category').innerHTML=categories.map(([value,label])=>`<option value="${value}">${label}</option>`).join('');
  $('#cash-flow-owner').innerHTML=h.persons.map(person=>`<option value="${escapeHtml(person.slot)}">${escapeHtml(person.display_name)}</option>`).join('')+(h.mode==='couple'?'<option value="joint">Gemeinsam</option>':'');
  $('#cash-flow-owner-field').hidden=h.mode==='single';
  const defaultAccount=h.accounts.find(account=>account.is_default);
  $('#cash-flow-account').innerHTML='<option value="">Kein Konto zugeordnet</option>'+h.accounts.map(account=>`<option value="${escapeHtml(account.id)}">${escapeHtml(account.name)}${account.is_default?' · Standard':''}</option>`).join('');
  form.elements.owner.value='A';form.elements.account_id.value=defaultAccount?.id||'';form.elements.due_date.value=state.asOf;form.elements.active.checked=true;
  if(item){form.elements.name.value=item.name;form.elements.category.value=item.category;form.elements.owner.value=slotForOwner(item);form.elements.amount.value=(Number(item.amount_cents)/100).toFixed(2);form.elements.recurrence.value=item.recurrence;form.elements.due_date.value=item.due_date;form.elements.end_date.value=item.end_date||'';form.elements.duration_months.value=item.duration_months||'';form.elements.account_id.value=item.account_id||'';form.elements.credit_id.value=item.credit_id||'';form.elements.credit_reduction.value=item.credit_id?(Number(item.credit_reduction_cents||0)/100).toFixed(2):'';form.elements.active.checked=Boolean(item.configured_active)}
  configureFlowCreditFields();if(item?.credit_id)form.elements.credit_id.value=item.credit_id;
  $('#cash-flow-dialog-eyebrow').textContent=item?(kind==='income'?'EINNAHME BEARBEITEN':'AUSGABE BEARBEITEN'):(kind==='income'?'NEUE EINNAHME':'NEUE AUSGABE');
  $('#cash-flow-dialog-title').textContent=item?'Position bearbeiten':(kind==='income'?'Einnahme anlegen':'Ausgabe anlegen');$('#delete-cash-flow').hidden=!item;$('#cash-flow-error').hidden=true;$('#cash-flow-dialog').showModal()
}
$('#new-income').addEventListener('click',()=>openFlow('income'));$('#new-expense').addEventListener('click',()=>{state.expenseFilter='active';openFlow('expense')});$('#dashboard-new-income').addEventListener('click',()=>openFlow('income'));$('#dashboard-new-expense').addEventListener('click',()=>{state.expenseFilter='active';openFlow('expense')});
$('#cash-flow-form').elements.duration_months.addEventListener('input',syncFlowEndFromDuration);$('#cash-flow-form').elements.due_date.addEventListener('change',()=>{if($('#cash-flow-form').elements.duration_months.value)syncFlowEndFromDuration();else syncFlowDurationFromEnd()});$('#cash-flow-form').elements.end_date.addEventListener('change',syncFlowDurationFromEnd);$('#cash-flow-form').elements.category.addEventListener('change',configureFlowCreditFields);
function flowClick(event){const button=event.target.closest('[data-edit-flow]');if(!button)return;const kind=button.dataset.editFlowKind,item=flowById(kind,button.dataset.editFlow);if(item)openFlow(kind,item)}
