$('#cash-flow-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget.elements,error=$('#cash-flow-error'),button=event.submitter,isCredit=state.editingFlowKind==='expense'&&creditCategories.has(form.category.value);button.disabled=true;error.hidden=true;const payload={household_id:state.currentId,kind:state.editingFlowKind,name:form.name.value,category:form.category.value,amount_cents:euroCents(form.amount.value),recurrence:form.recurrence.value,due_date:form.due_date.value,end_date:state.editingFlowKind==='expense'?form.end_date.value:'',duration_months:state.editingFlowKind==='expense'?form.duration_months.value:'',account_id:form.account_id.value,credit_id:isCredit?form.credit_id.value:'',credit_reduction_cents:isCredit?(form.credit_reduction.value===''?'':euroCents(form.credit_reduction.value)):'',owner:form.owner.value,active:form.active.checked};try{await api(state.editingFlowId?`/api/cash-flows/${encodeURIComponent(state.editingFlowId)}`:'/api/cash-flows',{method:state.editingFlowId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(state.editingFlowKind==='expense'){const archiveDate=payload.end_date||(payload.recurrence==='once'?payload.due_date:'');state.expenseFilter=archiveDate&&archiveDate<today()?'archive':'active'}$('#cash-flow-dialog').close();state.editingFlowId=null;await loadAll();toast('Position wurde gespeichert.')}catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false}});
$('#delete-cash-flow').addEventListener('click',async()=>{const item=flowById(state.editingFlowKind,state.editingFlowId);if(!item||!confirm(`„${item.name}“ wirklich löschen?`))return;try{await api(`/api/cash-flows/${encodeURIComponent(item.id)}?household_id=${encodeURIComponent(state.currentId)}`,{method:'DELETE'});$('#cash-flow-dialog').close();state.editingFlowId=null;await loadAll();toast('Position wurde gelöscht.')}catch(err){toast(err.message)}});

function openCredit(item=null){state.editingCreditId=item?.id||null;const form=$('#credit-form');form.reset();form.elements.credit_type.value=item?.credit_type||'consumer_credit';form.elements.opening_balance.value=item?(Number(item.opening_balance_cents)/100).toFixed(2):'';form.elements.name.value=item?.name||'';form.elements.note.value=item?.note||'';$('#credit-dialog-title').textContent=item?'Kredit bearbeiten':'Kredit anlegen';$('#delete-credit').hidden=!item;$('#credit-error').hidden=true;$('#credit-dialog').showModal()}
async function openCreditDetail(creditId){const credit=await api(`/api/credits/${encodeURIComponent(creditId)}?household_id=${encodeURIComponent(state.currentId)}&as_of=${encodeURIComponent(today())}`);state.currentCreditId=credit.id;$('#credit-detail-type').textContent=creditTypeLabels[credit.credit_type]||'KREDIT';$('#credit-detail-title').textContent=credit.name;$('#credit-detail-summary').innerHTML=summaryCard('Anfangssaldo',credit.opening_balance_cents)+summaryCard('Bisher getilgt',credit.paid_cents)+summaryCard('Offener Saldo',credit.remaining_balance_cents);$('#credit-payment-list').innerHTML=credit.payments.length?credit.payments.map(creditPaymentRow).join(''):'<p class="empty">Noch keine Tilgungen vorhanden.</p>';const form=$('#credit-payment-form');form.reset();form.elements.payment_date.value=today();$('#credit-payment-error').hidden=true;if(!$('#credit-detail-dialog').open)$('#credit-detail-dialog').showModal()}
$('#new-credit').addEventListener('click',()=>openCredit());
$('#credit-filter').addEventListener('click',event=>{const button=event.target.closest('[data-credit-filter]');if(!button)return;state.creditFilter=button.dataset.creditFilter;renderCredits()});
$('#credit-list').addEventListener('click',event=>{const edit=event.target.closest('[data-edit-credit]');if(edit){const item=creditById(edit.dataset.editCredit);if(item)openCredit(item);return}const row=event.target.closest('[data-open-credit]');if(row)openCreditDetail(row.dataset.openCredit).catch(err=>toast(err.message))});
$('#credit-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget.elements,error=$('#credit-error'),button=event.submitter;error.hidden=true;button.disabled=true;const payload={household_id:state.currentId,name:form.name.value,credit_type:form.credit_type.value,opening_balance_cents:euroCents(form.opening_balance.value),note:form.note.value};try{await api(state.editingCreditId?`/api/credits/${encodeURIComponent(state.editingCreditId)}`:'/api/credits',{method:state.editingCreditId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});state.creditFilter=payload.credit_type;$('#credit-dialog').close();state.editingCreditId=null;await loadAll();toast('Kredit wurde gespeichert.')}catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false}});
$('#delete-credit').addEventListener('click',async()=>{const item=creditById(state.editingCreditId);if(!item||!confirm(`„${item.name}“ mit seiner Zahlungshistorie wirklich löschen? Verknüpfte Ausgaben bleiben als normale Ausgaben erhalten.`))return;try{await api(`/api/credits/${encodeURIComponent(item.id)}?household_id=${encodeURIComponent(state.currentId)}`,{method:'DELETE'});$('#credit-dialog').close();state.editingCreditId=null;state.previewCreditIds=state.previewCreditIds.filter(id=>id!==item.id);await loadAll();toast('Kredit wurde gelöscht.')}catch(err){toast(err.message)}});
$('#credit-payment-form').addEventListener('submit',async event=>{event.preventDefault();if(!state.currentCreditId)return;const form=event.currentTarget.elements,error=$('#credit-payment-error'),button=event.submitter;error.hidden=true;button.disabled=true;const payload={household_id:state.currentId,payment_date:form.payment_date.value,amount_cents:euroCents(form.amount.value),note:form.note.value};try{await api(`/api/credits/${encodeURIComponent(state.currentCreditId)}/payments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await loadAll();await openCreditDetail(state.currentCreditId);toast('Tilgung wurde gespeichert.')}catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false}});
$('#credit-payment-list').addEventListener('click',async event=>{const button=event.target.closest('[data-delete-credit-payment]');if(!button||!state.currentCreditId)return;if(!confirm('Diese manuelle Tilgung wirklich löschen?'))return;try{await api(`/api/credits/${encodeURIComponent(state.currentCreditId)}/payments/${encodeURIComponent(button.dataset.deleteCreditPayment)}?household_id=${encodeURIComponent(state.currentId)}`,{method:'DELETE'});await loadAll();await openCreditDetail(state.currentCreditId);toast('Tilgung wurde gelöscht.')}catch(err){toast(err.message)}});

function openTransfer(item=null){const accounts=state.dashboard.household.accounts;if(accounts.length<2){toast('Für eine Umbuchung werden mindestens zwei Konten benötigt.');showView('accounts');return}state.editingTransferId=item?.id||null;const form=$('#transfer-form');form.reset();const options=accounts.map(account=>`<option value="${escapeHtml(account.id)}">${escapeHtml(account.name)}</option>`).join('');$('#transfer-source').innerHTML=options;$('#transfer-target').innerHTML=options;const defaultAccount=accounts.find(account=>account.is_default)||accounts[0];form.elements.source_account_id.value=item?.source_account_id||defaultAccount.id;form.elements.target_account_id.value=item?.target_account_id||accounts.find(account=>account.id!==form.elements.source_account_id.value).id;form.elements.name.value=item?.name||'Umbuchung';form.elements.amount.value=item?(Number(item.amount_cents)/100).toFixed(2):'';form.elements.due_date.value=item?.due_date||state.asOf;form.elements.recurrence.value=item?.recurrence||'once';form.elements.end_date.value=item?.end_date||'';form.elements.occurrence_count.value=item?.occurrence_count||'';form.elements.active.checked=item?Boolean(item.active):true;$('#transfer-dialog-title').textContent=item?'Umbuchung bearbeiten':'Umbuchung anlegen';$('#delete-transfer').hidden=!item;$('#transfer-error').hidden=true;$('#transfer-dialog').showModal()}
$('#new-transfer').addEventListener('click',()=>{state.transferFilter='active';openTransfer()});$('#transfer-list').addEventListener('click',event=>{const button=event.target.closest('[data-edit-transfer]');if(button){const item=state.transfers.find(entry=>entry.id===button.dataset.editTransfer);if(item)openTransfer(item)}});$('#transfer-filter').addEventListener('click',event=>{const button=event.target.closest('[data-transfer-filter]');if(!button)return;state.transferFilter=button.dataset.transferFilter;renderTransfers()});
$('#transfer-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget.elements,error=$('#transfer-error'),button=event.submitter,limitError=transferLimitError(form);error.hidden=true;if(limitError){error.textContent=limitError;error.hidden=false;form.end_date.focus();return}button.disabled=true;const payload={household_id:state.currentId,name:form.name.value,source_account_id:form.source_account_id.value,target_account_id:form.target_account_id.value,amount_cents:euroCents(form.amount.value),due_date:form.due_date.value,recurrence:form.recurrence.value,end_date:form.end_date.value,occurrence_count:form.occurrence_count.value,active:form.active.checked};try{await api(state.editingTransferId?`/api/transfers/${encodeURIComponent(state.editingTransferId)}`:'/api/transfers',{method:state.editingTransferId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const archiveDate=payload.end_date||(payload.recurrence==='once'?payload.due_date:'');state.transferFilter=archiveDate&&archiveDate<today()?'archive':'active';$('#transfer-dialog').close();state.editingTransferId=null;await loadAll();toast('Umbuchung wurde gespeichert.')}catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false}});
$('#delete-transfer').addEventListener('click',async()=>{const item=state.transfers.find(entry=>entry.id===state.editingTransferId);if(!item||!confirm(`„${item.name}“ wirklich löschen?`))return;try{await api(`/api/transfers/${encodeURIComponent(item.id)}?household_id=${encodeURIComponent(state.currentId)}`,{method:'DELETE'});$('#transfer-dialog').close();state.editingTransferId=null;await loadAll();toast('Umbuchung wurde gelöscht.')}catch(err){toast(err.message)}});

$('#household-select').addEventListener('change',async event=>{state.currentId=event.target.value;state.previewAccountIds=[];state.previewCreditIds=[];state.expenseFilter='active';state.transferFilter='active';state.creditFilter='all';await loadAll()});
$('#delete-household').addEventListener('click',async()=>{const current=state.households.find(h=>h.id===state.currentId);if(!current||!confirm(`Haushalt „${current.name}“ einschließlich aller Daten endgültig löschen?`))return;try{await api(`/api/households/${encodeURIComponent(current.id)}`,{method:'DELETE'});state.households=(await api('/api/households')).items;state.currentId=state.households[0]?.id||null;if(state.currentId)await loadAll();else openSetup(true);toast('Haushalt wurde gelöscht.')}catch(err){toast(err.message)}});

$('#open-excel-export').addEventListener('click',()=>{const form=$('#excel-export-form');form.elements.from_month.value=monthNow();form.elements.through_month.value=shiftMonth(monthNow(),11);$('#excel-export-error').hidden=true;$('#excel-export-dialog').showModal()});
$('#excel-export-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget.elements,error=$('#excel-export-error'),button=event.submitter;error.hidden=true;button.disabled=true;button.textContent='Excel wird erstellt …';try{const query=new URLSearchParams({household_id:state.currentId,from_month:form.from_month.value,through_month:form.through_month.value});const response=await fetch(`/api/export.xlsx?${query}`);if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'Der Excel-Export konnte nicht erstellt werden.')}const blob=await response.blob(),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/),filename=match?.[1]||`Haushaltsplaner-${form.from_month.value}-bis-${form.through_month.value}.xlsx`,url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#excel-export-dialog').close();toast('Die Excel-Arbeitsmappe wurde erstellt.')}catch(err){error.textContent=err.message;error.hidden=false}finally{button.disabled=false;button.textContent='Excel herunterladen'}});
$$('[data-close]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.close).close()));
boot().catch(error=>{$('#app').hidden=false;toast(`Die Anwendung konnte nicht gestartet werden: ${error.message}`)});
